const cfg = $('Config').first().json;
const base = String(cfg.grist_base_url || '').replace(/\/+$/, '');
const clinics = ($input.first().json.records || []).filter(
  (r) => r.fields && r.fields.Active === true && String(r.fields.Grist_Doc_ID || '').trim()
);
return clinics.map((r) => ({
  json: {
    grist_base_url: base,
    doc_id: String(r.fields.Grist_Doc_ID).trim(),
    clinic_slug: String(r.fields.Clinic_Slug || ''),
    registry_clinic_name: String(r.fields.Clinic_Name || ''),
  },
  pairedItem: { item: 0 },
}));

// Pasted from n8n/snippets/clinic-hours.js - keep identical.
const DAY_INDEX = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };

function parseClock(text) {
  const m = String(text === null || text === undefined ? '' : text).trim().match(/^(\d{1,2})(?:[:.](\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?$/i);
  if (!m) return null;
  let h = parseInt(m[1], 10);
  const min = m[2] ? parseInt(m[2], 10) : 0;
  const meridiem = m[3] ? m[3][0].toLowerCase() : '';
  if (min > 59) return null;
  if (meridiem) {
    if (h < 1 || h > 12) return null;
    h = (h % 12) + (meridiem === 'p' ? 12 : 0);
  } else if (h > 24 || (h === 24 && min > 0)) {
    return null;
  }
  return h * 60 + min;   // minutes after midnight
}

function parseDays(text) {
  const s = String(text === null || text === undefined ? '' : text).toLowerCase().replace(/[–—]/g, '-').replace(/\s+to\s+/g, '-').replace(/\s+(and|&)\s+/g, ',').trim();
  if (!s) return null;
  if (/^(daily|every ?day|all days|7 ?days?)$/.test(s)) return [0, 1, 2, 3, 4, 5, 6];
  const dayOf = (t) => {
    const x = t.trim();
    return /^(sun|mon|tue|wed|thu|fri|sat)[a-z]*\.?$/.test(x) ? DAY_INDEX[x.slice(0, 3)] : undefined;
  };
  const days = new Set();
  for (const token of s.split(/[,;/]+/)) {
    if (!token.trim()) continue;
    if (token.includes('-')) {
      const [a, b] = token.split('-').map(dayOf);
      if (a === undefined || b === undefined) return null;
      for (let d = a; ; d = (d + 1) % 7) { days.add(d); if (d === b) break; }
    } else {
      const d = dayOf(token);
      if (d === undefined) return null;
      days.add(d);
    }
  }
  return days.size ? [...days].sort() : null;   // 0 = Sunday
}

function isOpenNow(i) {
  if (!Number.isFinite(i.now_ms)) return { open: false, source: 'default' };
  let open = parseClock(i.open_time);
  let close = parseClock(i.close_time);
  let days = parseDays(i.working_days);
  let source = 'settings';
  if (open === null || close === null || close <= open) { open = 8 * 60; close = 21 * 60; source = 'default'; }
  if (days === null) { days = [0, 1, 2, 3, 4, 5, 6]; source = 'default'; }
  const t = new Date(i.now_ms + 5.5 * 3600 * 1000);   // IST wall-clock via UTC getters
  const minutes = t.getUTCHours() * 60 + t.getUTCMinutes();
  return { open: days.includes(t.getUTCDay()) && minutes >= open && minutes < close, source };
}

  const clinics = $('Split clinics').all();
  return $input.all().map((item, i) => {
    const s = {};
    for (const r of item.json.records || []) {
      const f = r.fields || {};
      if (f.Key) s[String(f.Key).trim()] = f.Value;
    }
    const hours = isOpenNow({ open_time: s.open_time, close_time: s.close_time, working_days: s.working_days, now_ms: Date.now() });
    return {
      json: {
        ...clinics[i].json,
        clinic_name: String(s.clinic_name || clinics[i].json.registry_clinic_name || ''),
        owner_phone: s.owner_phone,
        test_mode: s.TEST_MODE,         // raw text; a missing row means TEST_MODE is ON (see send-guard.js)
        test_phone: s.TEST_PHONE,
        open_now: hours.open,
        hours_source: hours.source,      // 'default' = open_time / close_time / working_days missing or unreadable
      },
      pairedItem: { item: i },
    };
  });

const cfg = $('Config').first().json;
const nowMs = Date.now();
const minAge = Number(cfg.new_for_minutes);           // waiting at least this long ...
const maxAge = Number(cfg.max_age_hours) * 60;        // ... but not an old backlog
const cap = Number(cfg.max_alerts_per_run);           // per clinic per run, oldest first
const clinics = $('Add settings').all();
const out = [];

$input.all().forEach((item, i) => {
  const base = clinics[i].json;
  if (!base.open_now) return;                         // outside clinic hours: leave everything for the next run

  const due = (item.json.records || [])
    .filter((r) => {
      const f = r.fields || {};
      if (f.Status !== 'New' || f.Escalated || typeof f.Created_At !== 'number') return false;
      const minutes = (nowMs - f.Created_At * 1000) / 60000;
      return minutes >= minAge && minutes <= maxAge;
    })
    .sort((a, b) => a.fields.Created_At - b.fields.Created_At)
    .slice(0, cap);

  for (const r of due) {
    const f = r.fields;
    out.push({
      json: {
        ...base,
        lead_row_id: r.id,
        lead_id: f.Lead_ID || `row ${r.id}`,
        lead_name: String(f.Name || ''),
        lead_phone: String(f.Phone || ''),
        source: String(f.Source || ''),
        enquiry: String(f.Enquiry || '').replace(/\s+/g, ' ').trim().slice(0, 200),
        waiting_minutes: Math.floor((nowMs - f.Created_At * 1000) / 60000),
        escalated: !!f.Escalated,
      },
      pairedItem: { item: i },
    });
  }
});
return out;

// Pasted from n8n/snippets/normalize-phone.js and n8n/snippets/send-guard.js - keep identical.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  let digits = String(raw).replace(/\D/g, '');          // keep digits only
  if (digits.startsWith('0091')) digits = digits.slice(4);
  else if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
  else if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1);
  const valid = /^[6-9]\d{9}$/.test(digits);            // Indian mobiles start 6-9
  return { phone: valid ? `+91${digits}` : null, valid };
}

function isTestMode(value) {
  const v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  return !['false', '0', 'no', 'off'].includes(v);   // anything else, including a missing row, means ON (fail safe)
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

function decideSend(i) {
  const testMode = isTestMode(i.test_mode);
  const skip = (reason) => ({ send: false, to: null, reason, test_mode: testMode });

  if (i.flag_value) return skip('already sent');
  if (i.opted_out) return skip('opted out');
  if (i.kind !== 'transactional' && i.automation_paused) return skip('automation paused');
  if (inQuietHours(i.now_ms)) return skip('quiet hours');

  const to = testMode ? i.test_phone : i.patient_phone;
  if (!to) return skip(testMode ? 'test mode on but TEST_PHONE is missing or invalid' : 'no valid patient phone');
  return { send: true, to, reason: testMode ? 'test mode: sent to TEST_PHONE' : 'ok', test_mode: testMode };
}

  const { phone: owner_phone } = normalizeIndianPhone($json.owner_phone);
  const { phone: test_phone } = normalizeIndianPhone($json.test_phone);
  const decision = decideSend({
    kind: 'transactional',
    flag_value: $json.escalated ? 1 : null,    // the Escalated toggle is this alert's "sent" flag (rule 4)
    opted_out: false,
    automation_paused: false,
    patient_phone: owner_phone,                // "patient_phone" is just the guard's name for the recipient
    test_mode: $json.test_mode,
    test_phone,
    now_ms: Date.now(),
  });
  return { json: { ...$json, decision, send: decision.send } };

const who = $json.lead_name || 'no name';
const quote = $json.enquiry ? ` - "${$json.enquiry}"` : '';
return {
  json: {
    ...$json,
    template: 'new_lead_staff_alert',
    template_params: {
      clinic_name: $json.clinic_name, lead_name: who, lead_phone: $json.lead_phone, source: $json.source,
      waiting_minutes: $json.waiting_minutes, enquiry: $json.enquiry,
    },
    message_text: `Lead waiting ${$json.waiting_minutes} min with no response (${$json.clinic_name}): ${who}, ${$json.lead_phone}${quote}. ${$json.lead_id}.`,
    sent: false,
    stub: true,
  },
};

const now = Math.floor(Date.now() / 1000);
return {
  json: {
    ...$json,
    patch: { records: [{ id: $json.lead_row_id, fields: { Escalated: true } }] },
    log: { Workflow: 'W3-speed-to-lead', Record: `${$json.lead_id} (escalated)`, Outcome: 'ok', Error: '', At: now },
  },
};
